j:jelly.script:
//
// show link if populated, hide if not 
//
function onChange_cmdb_ci_bsm(element, original, changed, loading) {
  var visibility = 'hidden';
   if (changed.length > 0)
    visibility = 'visible';

  var e = gel('${jvar_n}');
  e.style.visibility= visibility;
}

// show map if the sys_id is populated
function showMap(name) {
  var fieldName = name.split(':')[1];
  var n = gel(fieldName); 
  n = n.value; 
  if (n.length == 0) {  
   alert("Populate CI field first"); 
  } else {
    showBSMMap(n, fieldName); 
  }
}

// generic show bsm map function for sys_id
function showBSMMap(sys_id, fieldName) {
  var url =  '';
  if ("${jvar_plugin}" == "true")
  	url += '$ngbsm.do?sysparm_nameofstack=bsm';
  else
  	url += 'bsm_map2.do?sysparm_nameofstack=bsm';
  url += '&amp;';
  url += 'sysparm_attributes=table=cmdb_ci';
  url += '&amp;';
  url += 'sysparm_nostack=true'; //PRB675289 - support 'back' correctly
  url += '&amp;';	
  url += 'id=' + sys_id;
  url += '&amp;';
  url += 'level=3';
  url += '&amp;';
  url += 'ref=' + fieldName; 
  url += '&amp;';
  url += 'ciview=';
  url += '&amp;';
  url += 'restack=true';

  g_navigation.open(url, 'super_bsm_map');
}

// create a handler for each table in the array
var a = ['incident',  'change_request', 'problem'];
for (i = 0; i &lt; a.length; i++) {
  var h = new GlideEventHandler('onChange_' + a[i] + '_cmdb_ci_bsm', onChange_cmdb_ci_bsm, '${ref}');
  g_event_handlers.push(h);
}
